(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  let scrolled = false;
  const btn = Array.from(document.querySelectorAll('button')).find(b => /Confirm\s*OTP/i.test((b.innerText||'').replace(/\s+/g,' ')));
  if (btn) { try { btn.scrollIntoView({block:'start', behavior:'instant'}); scrolled = true; } catch(e) {} }
  await sleep(1000);
  const info = [];
  let n = btn;
  for (let i=0;i<8 && n;i++){ info.push({tag:n.tagName, id:n.id, cls:(n.className||'').toString().slice(0,30), st:n.scrollTop}); n = n.parentElement; }
  return JSON.stringify({scrolled, info: info.filter(x=>x.st>0 || x.id)});
})()
